from .errors import ParseError
from .lexer import tokenize


@dataclass(frozen=True)
class Number:
    value: float
    position: int


@dataclass(frozen=True)
class String:
    value: str
    position: int


@dataclass(frozen=True)
class Boolean:
    value: bool
    position: int


@dataclass(frozen=True)
class Variable:
    name: str
    position: int


@dataclass(frozen=True)
class Call:
    name: str
    args: tuple
    position: int


@dataclass(frozen=True)
class Unary:
    op: str  # "-" or "not"
    operand: object
    position: int


@dataclass(frozen=True)
class Binary:
    op: str  # arithmetic, comparison, "and", "or"
    left: object
    right: object
    position: int


COMPARISONS = {"==", "!=", "<", "<=", ">", ">="}


class _Parser:
    def __init__(self, tokens, length):
        self.tokens = tokens
        self.length = length
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else None

    def next(self):
        tok = self.peek()
        if tok is None:
            raise ParseError("unexpected end of input", self.length)
        self.i += 1
        return tok

    def is_op(self, *ops):
        t = self.peek()
        return t is not None and t.kind == "OP" and t.value in ops

    def is_kw(self, kw):
        t = self.peek()
        return t is not None and t.kind == "KEYWORD" and t.value == kw

    def parse_all(self):
        node = self.expr()
        t = self.peek()
        if t is not None:
            raise ParseError(f"unexpected token: {t.value!r}", t.position)
        return node

    def expr(self):
        node = self.and_expr()
        while self.is_kw("or"):
            t = self.next()
            node = Binary("or", node, self.and_expr(), t.position)
        return node

    def and_expr(self):
        node = self.not_expr()
        while self.is_kw("and"):
            t = self.next()
            node = Binary("and", node, self.not_expr(), t.position)
        return node

    def not_expr(self):
        if self.is_kw("not"):
            t = self.next()
            return Unary("not", self.not_expr(), t.position)
        return self.comparison()

    def comparison(self):
        node = self.additive()
        if self.is_op(*COMPARISONS):
            t = self.next()
            node = Binary(t.value, node, self.additive(), t.position)
            if self.is_op(*COMPARISONS):
                raise ParseError("comparison operators cannot be chained", self.peek().position)
        return node

    def additive(self):
        node = self.multiplicative()
        while self.is_op("+", "-"):
            t = self.next()
            node = Binary(t.value, node, self.multiplicative(), t.position)
        return node

    def multiplicative(self):
        node = self.unary()
        while self.is_op("*", "/", "%"):
            t = self.next()
            node = Binary(t.value, node, self.unary(), t.position)
        return node

    def unary(self):
        if self.is_op("-"):
            t = self.next()
            return Unary("-", self.unary(), t.position)
        return self.power()

    def power(self):
        node = self.primary()
        if self.is_op("^"):
            t = self.next()
            node = Binary("^", node, self.unary(), t.position)
        return node

    def primary(self):
        t = self.next()
        if t.kind == "NUMBER":
            return Number(t.value, t.position)
        if t.kind == "STRING":
            return String(t.value, t.position)
        if t.kind == "KEYWORD" and t.value in ("true", "false"):
            return Boolean(t.value == "true", t.position)
        if t.kind == "IDENT":
            if self.is_op("("):
                self.next()
                args = []
                if self.is_op(")"):
                    self.next()
                else:
                    args.append(self.expr())
                    while self.is_op(","):
                        self.next()
                        args.append(self.expr())
                    close = self.next()
                    if not (close.kind == "OP" and close.value == ")"):
                        raise ParseError("expected ')' or ','", close.position)
                return Call(t.value, tuple(args), t.position)
            return Variable(t.value, t.position)
        if t.kind == "OP" and t.value == "(":
            node = self.expr()
            close = self.next()
            if not (close.kind == "OP" and close.value == ")"):
                raise ParseError("expected ')'", close.position)
            return node
        raise ParseError(f"unexpected token: {t.value!r}", t.position)


def parse(source):
    return _Parser(tokenize(source), len(source)).parse_all()

import re

from .errors import EvalError

_NUM_RE = re.compile(r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?", re.ASCII)
_ESC_OUT = {"\n": "\\n", "\t": "\\t", "\r": "\\r", '"': '\\"', "\\": "\\\\"}


def format_number(x):
    if x.is_integer():
        return str(int(x))
    return repr(x)


def format_value(v):
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, float):
        return format_number(v)
    if isinstance(v, str):
        return '"' + "".join(_ESC_OUT.get(c, c) for c in v) + '"'
    return repr(v)


def _is_num(v):
    return isinstance(v, float)


def _arity(name, args, expected):
    if len(args) != expected:
        raise EvalError(f"{name}() takes {expected} argument(s), got {len(args)}")


def _need(name, v, kind):
    ok = _is_num(v) if kind == "number" else isinstance(v, str)
    if not ok:
        raise EvalError(f"{name}() expects a {kind} argument")


def _abs(*args):
    _arity("abs", args, 1)
    _need("abs", args[0], "number")
    return abs(args[0])


def _extreme(name, fn):
    def f(*args):
        if not args:
            raise EvalError(f"{name}() takes at least 1 argument(s), got 0")
        for a in args:
            _need(name, a, "number")
        return fn(args)
    return f


def _round(*args):
    if len(args) not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")
    _need("round", args[0], "number")
    try:
        if len(args) == 1:
            return float(round(args[0]))
        _need("round", args[1], "number")
        if not args[1].is_integer():
            raise EvalError("round() digits must be a whole number")
        return float(round(args[0], int(args[1])))
    except (OverflowError, ValueError):
        raise EvalError("round() cannot round this value")


def _len(*args):
    _arity("len", args, 1)
    _need("len", args[0], "string")
    return float(len(args[0]))


def _upper(*args):
    _arity("upper", args, 1)
    _need("upper", args[0], "string")
    return args[0].upper()


def _lower(*args):
    _arity("lower", args, 1)
    _need("lower", args[0], "string")
    return args[0].lower()


def _str(*args):
    _arity("str", args, 1)
    v = args[0]
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return "true" if v else "false"
    return format_number(v)


def _num(*args):
    _arity("num", args, 1)
    _need("num", args[0], "string")
    s = args[0].strip()
    if not _NUM_RE.fullmatch(s):
        raise EvalError(f"num() cannot parse {args[0]!r}")
    return float(s)


BUILTINS = {
    "abs": _abs,
    "min": _extreme("min", min),
    "max": _extreme("max", max),
    "round": _round,
    "len": _len,
    "upper": _upper,
    "lower": _lower,
    "str": _str,
    "num": _num,
}
# `if` is lazy, so the evaluator handles it directly.
LAZY_BUILTINS = {"if"}

from .builtins import BUILTINS, LAZY_BUILTINS
from .errors import EvalError
from .parser import Binary, Boolean, Call, Number, String, Unary, Variable, parse


def _is_num(v):
    return isinstance(v, float)


def _require_bool(v, what):
    if not isinstance(v, bool):
        raise EvalError(f"{what} requires a boolean")
    return v


def _both_numbers(op, a, b):
    if not (_is_num(a) and _is_num(b)):
        raise EvalError(f"operator {op} requires numbers")


def _equal(a, b):
    if type(a) is not type(b):
        return False
    return a == b


def _binary(op, a, b):
    if op == "+":
        if _is_num(a) and _is_num(b):
            return a + b
        if isinstance(a, str) and isinstance(b, str):
            return a + b
        raise EvalError("operator + requires two numbers or two strings")
    if op in ("-", "*", "/", "%"):
        _both_numbers(op, a, b)
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            if b == 0:
                raise EvalError("division by zero")
            return a / b
        if b == 0:
            raise EvalError("modulo by zero")
        return a % b
    if op == "^":
        _both_numbers(op, a, b)
        try:
            r = a ** b
        except (ZeroDivisionError, OverflowError):
            raise EvalError("invalid power")
        if not isinstance(r, float):
            raise EvalError("power result is not a real number")
        return r
    if op == "==":
        return _equal(a, b)
    if op == "!=":
        return not _equal(a, b)
    if _is_num(a) and _is_num(b) or isinstance(a, str) and isinstance(b, str):
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b
    raise EvalError(f"operator {op} requires two numbers or two strings")


def _eval(node, env):
    if isinstance(node, (Number, String, Boolean)):
        return node.value
    if isinstance(node, Variable):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}")
        v = env[node.name]
        if type(v) not in (float, str, bool) and not (
            isinstance(v, (float, str, bool)) and not isinstance(v, int) or isinstance(v, bool)
        ):
            raise EvalError(f"unsupported value for {node.name}: {v!r}")
        return v
    if isinstance(node, Unary):
        v = _eval(node.operand, env)
        if node.op == "not":
            return not _require_bool(v, "not")
        if not _is_num(v):
            raise EvalError("unary - requires a number")
        return -v
    if isinstance(node, Binary):
        if node.op in ("and", "or"):
            left = _require_bool(_eval(node.left, env), node.op)
            if node.op == "and" and not left:
                return False
            if node.op == "or" and left:
                return True
            return _require_bool(_eval(node.right, env), node.op)
        return _binary(node.op, _eval(node.left, env), _eval(node.right, env))
    if isinstance(node, Call):
        if node.name in LAZY_BUILTINS:
            if len(node.args) != 3:
                raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
            cond = _require_bool(_eval(node.args[0], env), "if condition")
            return _eval(node.args[1 if cond else 2], env)
        fn = BUILTINS.get(node.name)
        if fn is None:
            raise EvalError(f"undefined function: {node.name}")
        return fn(*[_eval(a, env) for a in node.args])
    raise EvalError(f"unknown node: {node!r}")


def evaluate(source, env=None):
    tree = parse(source)
    return _eval(tree, {} if env is None else env)

