def _abs(*args):
    _arity("abs", args, 1)
    _need("abs", args[0], "number")
    return abs(args[0])


def _extreme(name, fn):
    def f(*args):
        if not args:
            raise EvalError(f"{name}() takes at least 1 argument(s), got 0")
        for a in args:
            _need(name, a, "number")
        return fn(args)
    return f


def _round(*args):
    if len(args) not in (1, 2):
        raise EvalError(f"round() takes 1 or 2 argument(s), got {len(args)}")
    _need("round", args[0], "number")
    if len(args) == 2:
        _need("round", args[1], "number")
        if not args[1].is_integer():
            raise EvalError("round() digits must be a whole number")
    try:
        if len(args) == 1:
            return float(round(args[0]))
        return float(round(args[0], int(args[1])))
    except (OverflowError, ValueError):
        raise EvalError("round() cannot round this value")


def _len(*args):
    _arity("len", args, 1)
    _need("len", args[0], "string")
    return float(len(args[0]))


def _upper(*args):
    _arity("upper", args, 1)
    _need("upper", args[0], "string")
    return args[0].upper()


def _lower(*args):
    _arity("lower", args, 1)
    _need("lower", args[0], "string")
    return args[0].lower()


def _str(*args):
    _arity("str", args, 1)
    v = args[0]
    if isinstance(v, str):
        return v
    if isinstance(v, bool):
        return "true" if v else "false"
    return format_number(v)


def _num(*args):
    _arity("num", args, 1)
    _need("num", args[0], "string")
    s = args[0].strip()
    if not _NUM_RE.fullmatch(s):
        raise EvalError(f"num() cannot parse {args[0]!r}")
    return float(s)


BUILTINS = {
    "abs": _abs,
    "min": _extreme("min", min),
    "max": _extreme("max", max),
    "round": _round,
    "len": _len,
    "upper": _upper,
    "lower": _lower,
    "str": _str,
    "num": _num,
}
# `if` is lazy, so the evaluator handles it directly.
LAZY_BUILTINS = {"if"}

from .builtins import BUILTINS, LAZY_BUILTINS
from .errors import EvalError
from .parser import Binary, Boolean, Call, Number, String, Unary, Variable, parse


def _is_num(v):
    return isinstance(v, float)


def _require_bool(v, what):
    if not isinstance(v, bool):
        raise EvalError(f"{what} requires a boolean")
    return v


def _equal(a, b):
    if type(a) is not type(b):
        return False
    return a == b


def _binary(op, a, b):
    if op == "+":
        if _is_num(a) and _is_num(b):
            return a + b
        if isinstance(a, str) and isinstance(b, str):
            return a + b
        raise EvalError("operator + requires two numbers or two strings")
    if op in ("-", "*", "/", "%", "^"):
        if not (_is_num(a) and _is_num(b)):
            raise EvalError(f"operator {op} requires numbers")
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        if op == "/":
            if b == 0:
                raise EvalError("division by zero")
            return a / b
        if op == "%":
            if b == 0:
                raise EvalError("modulo by zero")
            return a % b
        try:
            r = a ** b
        except (ZeroDivisionError, OverflowError):
            raise EvalError("invalid power")
        if not isinstance(r, float):
            raise EvalError("power result is not a real number")
        return r
    if op == "==":
        return _equal(a, b)
    if op == "!=":
        return not _equal(a, b)
    if (_is_num(a) and _is_num(b)) or (isinstance(a, str) and isinstance(b, str)):
        if op == "<":
            return a < b
        if op == "<=":
            return a <= b
        if op == ">":
            return a > b
        return a >= b
    raise EvalError(f"operator {op} requires two numbers or two strings")


def _eval(node, env):
    if isinstance(node, (Number, String, Boolean)):
        return node.value
    if isinstance(node, Variable):
        if node.name not in env:
            raise EvalError(f"undefined variable: {node.name}")
        v = env[node.name]
        if not isinstance(v, (float, str, bool)):
            raise EvalError(f"unsupported value for {node.name}: {v!r}")
        return v
    if isinstance(node, Unary):
        v = _eval(node.operand, env)
        if node.op == "not":
            return not _require_bool(v, "not")
        if not _is_num(v):
            raise EvalError("unary - requires a number")
        return -v
    if isinstance(node, Binary):
        if node.op in ("and", "or"):
            left = _require_bool(_eval(node.left, env), node.op)
            if node.op == "and" and not left:
                return False
            if node.op == "or" and left:
                return True
            return _require_bool(_eval(node.right, env), node.op)
        return _binary(node.op, _eval(node.left, env), _eval(node.right, env))
    if isinstance(node, Call):
        if node.name in LAZY_BUILTINS:
            if len(node.args) != 3:
                raise EvalError(f"if() takes 3 argument(s), got {len(node.args)}")
            cond = _require_bool(_eval(node.args[0], env), "if condition")
            return _eval(node.args[1 if cond else 2], env)
        fn = BUILTINS.get(node.name)
        if fn is None:
            raise EvalError(f"undefined function: {node.name}")
        return fn(*[_eval(a, env) for a in node.args])
    raise EvalError(f"unknown node: {node!r}")


def evaluate(source, env=None):
    tree = parse(source)
    return _eval(tree, {} if env is None else env)

import re
import sys

from .builtins import format_value
from .errors import MiniLangError
from .evaluator import evaluate
from .lexer import KEYWORDS

_ASSIGN = re.compile(r"\s*([A-Za-z_][A-Za-z0-9_]*)\s*=(?!=)(.*)", re.DOTALL)


def main():
    env = {}
    out = sys.stdout
    for raw in sys.stdin:
        line = raw.strip()
        if not line:
            continue
        if line == ":quit":
            return 0
        if line == ":vars":
            for name in sorted(env):
                out.write(f"{name} = {format_value(env[name])}\n")
            continue
        try:
            m = _ASSIGN.fullmatch(line)
            if m and m.group(1) not in KEYWORDS:
                env[m.group(1)] = evaluate(m.group(2), env)
            else:
                out.write(format_value(evaluate(line, env)) + "\n")
        except MiniLangError as e:
            out.write(f"error: {e}\n")
    return 0


if __name__ == "__main__":
    sys.exit(main())
